from agent import *from models.products import *def run(context: dict[str, str], session: Session):    session.sessionbreakers = [SessionBreak(max_requests=6000)]    session.queue(Request("https://www.gamezoom.net/berichte"), process_catlist, dict())def process_catlist(data: Response, context: dict[str, str], session: Session):    cats1 = data.xpath("//div[@class='select-overlay__list']/div")    for cat1 in cats1:        cat1_name = cat1.xpath("p/text()").string()        section = cat1.xpath("p/@onclick").string().split("-")[0].split("'")[-1]        cats2 = cat1.xpath("div/p")        for cat2 in cats2:            cat2_name = cat2.xpath("text()").string()            group = cat2.xpath("@onclick").string().split("-")[-1].split("'")[0]            revs_url = "https://www.gamezoom.net/moreSearchTypeList?from=%s&to=%s&type=2&section=" + section + "&genre=0&group=" + group + "&term="            session.queue(Request(revs_url % ("0", "200")), process_revlist, dict(cat=cat1_name+'|'+cat2_name, revs_url=revs_url))def process_revlist(data: Response, context: dict[str, str], session: Session):    revs = data.xpath("//div[@class='news__day-container']")    for rev in revs:        name = rev.xpath(".//div[@class='news-entry__title']//text()").string(multiple=True)        url = rev.xpath('.//a/@href').string() + "-all"        if "Test/Review" in name:            session.queue(Request(url), process_review, dict(context, name=name, url=url))    if revs:        page = context.get("page", 1) + 1        session.queue(Request(context["revs_url"] % (str((page - 1) * 200), str(page * 200))), process_revlist, dict(context, page=page))def process_review(data: Response, context: dict[str, str], session: Session):    product = Product()    product.name = context["name"].split('-')[0].strip()    product.url = context["url"]    product.ssid = context["url"].split('-')[1]    product.category = context["cat"]    review = Review()    review.type = 'pro'    review.title = context["name"]    review.ssid = product.ssid    review.url = product.url    date = data.xpath("//div[@class='text-wrapper__article-details']/text()").string(multiple=True)    if date:        date = date.split('am ')[1].split(' - ')[0]        review.date = date    author_name = data.xpath("//div[@class='text-wrapper__article-details']/b/text()").string()    if author_name:        review.authors.append(Person(name=author_name, ssid=author_name))    grade_overall = data.xpath("//div[@class ='evaluation__chart']/div/text()").string(multiple=True)    if grade_overall:        grade_overall = int(grade_overall.split('%')[0])        if grade_overall > 100:            grade_overall = 100        review.grades.append(Grade(type="overall", value=grade_overall, best=100))    grades = data.xpath('//div[@class="valuation_part"]')    for grade in grades:        name = grade.xpath("div[@class='title']//text()").string()        value = grade.xpath("div[contains(@class, 'value_')]/@class").string()        value = int(value.split('_')[-1])        review.grades.append(Grade(name=name, value=int(value), best=10))    pros = data.xpath("//div[@class='pro']/ul/li//text()").strings()    for pro in pros:        review.add_property(type='pros', value=pro)    cons = data.xpath("//div[@class='contra']/ul/li//text()").strings()    for con in cons:        review.add_property(type='cons', value=con)    summary = data.xpath("//div[@class='text-wrapper__subtitle']/text()").string()    if summary:        review.add_property(type='summary', value=summary)    conclusion = data.xpath("//p[@class='evaluation__text']/text()").string()    if conclusion:        review.add_property(type='conclusion', value=conclusion)    excerpt = data.xpath("//div[@class='article_page']/span//text() | //div[@class='article_page']/text()").string(multiple=True)    if excerpt:        if summary:            excerpt = excerpt.replace(summary.strip(), '').strip()        if excerpt:            review.add_property(type='excerpt', value=excerpt)            product.reviews.append(review)            session.emit(product)